<script setup>
import { displayError, usePluginI18n } from '@framework/services/i18n';
const { t } = usePluginI18n('minimax-h3');

import { computed, ref, watch } from 'vue';
import { Icon } from '@iconify/vue';
import PluginDialog from '@framework/components/PluginDialog.vue';
const props=defineProps({session:Object,busy:Boolean,pending:Boolean,canAnswer:Boolean,answer:String});
const emit=defineEmits(['update:answer','confirm','answer','new-task']);
const selected=ref({});
const questions=computed(()=>props.session?.questions || []), stages=computed(()=>props.session?.progress?.stages || []), messages=computed(()=>props.session?.messages || []);
const directTextSubmission=computed(()=>props.session?.confirmation?.generation_payload?.capability_id==='video.text_to_video');
const confirmationOpen=ref(false), confirmationLanguage=ref('zh');
const confirmationText=computed(()=>confirmationLanguage.value==='zh'?props.session?.confirmation?.confirmed_prompt_zh:props.session?.confirmation?.execution_prompt_en);
const autoSubmitKey=ref(''), autoSubmitting=ref(false);
const answered=computed(()=>questions.value.filter(q=>selected.value[q.id||q.text]).length), allAnswered=computed(()=>questions.value.length>0&&answered.value===questions.value.length);
watch(()=>props.session?.id,()=>{selected.value={};confirmationOpen.value=false;confirmationLanguage.value='zh';},{immediate:true});
watch(()=>[directTextSubmission.value,props.session?.id,props.session?.revision,props.busy],([enabled,id,revision,busy])=>{
  const key=`${id}:${revision}`;
  if(!enabled){if(autoSubmitKey.value===key&&!busy)autoSubmitting.value=false;return;}
  if(autoSubmitKey.value!==key&&!busy){autoSubmitKey.value=key;autoSubmitting.value=true;emit('confirm');}
  else if(autoSubmitKey.value===key&&!busy)autoSubmitting.value=false;
},{immediate:true});
function choose(q,value){selected.value[q.id||q.text]=value;}
function stageMessage(stage){
  const message=stage.message || stage.status;
  const loaded=message?.match(/^已加载 (\d+) 项适用技能$/);
  return loaded?t('已加载 {count} 项适用技能',undefined,{count:loaded[1]}):t(message);
}
function submitAnswers(){const text=questions.value.map(q=>`${q.text||q.question}\n我的选择：${selected.value[q.id||q.text]}`).join('\n\n');emit('update:answer',text);emit('answer');selected.value={};}
</script>
<template><section v-if="session" class="collaboration-ui" aria-live="polite">
  <div class="conversation"><div v-for="(item,i) in messages" :key="i" class="message" :class="`is-${item.role || 'assistant'}`"><span>{{item.role==='user'?t("你"):'AI'}}</span><p>{{item.content||item.message}}</p></div><div v-if="pending" class="thinking"><i></i><i></i><i></i><span>{{t(session.message || "等待模型响应")}}</span></div><div v-if="session.error" class="error" role="alert"><Icon icon="solar:danger-triangle-linear" width="16"/>{{ displayError(session.error) }}</div>
    <section v-if="stages.length" class="stages"><div v-for="stage in stages" :key="stage.id" :class="`is-${stage.status}`"><Icon :icon="stage.status==='completed'?'solar:check-circle-bold':stage.status==='error'?'solar:danger-circle-bold':stage.status==='running'?'solar:refresh-circle-linear':'solar:circle-linear'" width="15"/><span><b>{{ t(stage.label) }}</b><small>{{ stageMessage(stage) }}</small></span></div></section>
    <section v-if="questions.length&&!pending" class="questions"><article v-for="q in questions" :key="q.id||q.text"><p>{{q.text||q.question}}</p><div class="options"><button v-for="option in q.options||[]" :key="option" type="button" :class="{selected:selected[q.id||q.text]===option}" @click="choose(q,option)">{{option}}</button></div></article><button v-if="allAnswered" class="submit-answers" type="button" @click="submitAnswers"><Icon icon="solar:check-circle-linear" width="15"/>{{ t("提交全部确认（{done}/{total}）", undefined, {done: answered, total: questions.length}) }}</button><small v-else>{{ t("请完成全部选择（{done}/{total}）", undefined, {done: answered, total: questions.length}) }}</small></section>
    <div v-if="autoSubmitting" class="thinking"><i></i><i></i><i></i><span>{{ t("已选择 T2VA，正在直接提交") }}</span></div>
    <section v-if="session.confirmation&&!pending&&!autoSubmitting" class="confirmation"><h4><Icon icon="solar:document-text-linear" width="15"/>{{ t("生成方案确认") }}</h4><p>{{session.confirmation.confirmed_prompt_zh}}</p><button class="view-confirmation" type="button" @click="confirmationLanguage='zh';confirmationOpen=true"><Icon icon="solar:eye-linear" width="15"/>{{ t("放大查看") }}</button></section>
  </div><div class="input-wrap"><textarea :value="answer" :disabled="!canAnswer" rows="1" :placeholder="t(&quot;补充人物、素材关系或镜头要求…&quot;)" @input="emit('update:answer',$event.target.value)" @keydown.enter.exact.prevent="canAnswer&&emit('answer')"></textarea><button type="button" :disabled="!canAnswer||!answer?.trim()" :aria-label="t(&quot;发送消息&quot;)" @click="emit('answer')"><Icon icon="solar:arrow-up-linear" width="17"/></button></div><footer v-if="session.confirmation&&!pending&&!autoSubmitting"><span><Icon icon="solar:check-circle-bold" width="15"/>{{ t("已完成生成前检查") }}</span><button type="button" :disabled="busy" @click="emit('confirm')"><Icon icon="solar:play-circle-linear" width="16"/>{{ t("按此方案生成") }}</button></footer>
  <PluginDialog :open="confirmationOpen" :title="t(&quot;生成方案&quot;)" @close="confirmationOpen=false">
    <div class="confirmation-viewer">
      <div class="confirmation-tabs" role="tablist" :aria-label="t(&quot;确认稿语言&quot;)">
        <button v-if="session.confirmation.confirmed_prompt_zh" type="button" role="tab" :aria-selected="confirmationLanguage==='zh'" :class="{active:confirmationLanguage==='zh'}" @click="confirmationLanguage='zh'">{{ t("中文确认稿") }}</button>
        <button v-if="session.confirmation.execution_prompt_en" type="button" role="tab" :aria-selected="confirmationLanguage==='en'" :class="{active:confirmationLanguage==='en'}" @click="confirmationLanguage='en'">{{ t("英文执行稿") }}</button>
      </div>
      <pre class="confirmation-full-text">{{confirmationText}}</pre>
    </div>
  </PluginDialog>
</section></template>
<style scoped>
.collaboration-ui{box-sizing:border-box;flex:1;height:100%;min-height:0;overflow:hidden;display:flex;flex-direction:column;color:#dfe6de;font-size:12px}.conversation{flex:1;min-height:0;max-height:none;overflow:auto;padding:14px 14px 2px;scrollbar-width:none}.conversation::-webkit-scrollbar{display:none}.message{display:flex;flex-direction:column;align-items:flex-start;gap:3px;margin:0 0 12px}.message.is-user{align-items:flex-end}.message span{color:#8f988d;font-size:10px}.message p{max-width:88%;margin:0;padding:8px 10px;border-radius:10px;background:#202426;color:#d7ded5;line-height:1.55;white-space:pre-wrap}.message.is-user p{background:#b7f34a;color:#18200f}.thinking{display:flex;gap:5px;align-items:center;margin:3px 0 12px;color:#969f95;font-size:10px}.thinking i{width:5px;height:5px;border-radius:50%;background:var(--lime);animation:blink 1.1s infinite}.thinking i:nth-child(2){animation-delay:.16s}.thinking i:nth-child(3){animation-delay:.32s}.error{display:flex;gap:6px;margin-bottom:12px;color:#f0a09a}.stages{display:grid;gap:2px;margin-bottom:12px;padding:8px 10px;border:1px solid #ffffff12;border-radius:8px;background:#121415}.stages>div{display:grid;grid-template-columns:18px 1fr;gap:7px;padding:5px 2px;color:#687168}.stages span{display:grid;gap:2px}.stages b{font-size:11px;font-weight:500}.stages small{color:#788078;font-size:9px}.stages .is-running{color:var(--lime)}.stages .is-completed{color:#a9cf70}.questions,.confirmation{margin-bottom:12px;padding-top:9px;border-top:1px solid #ffffff12}.questions p{margin:0 0 8px;line-height:1.5}.options{display:flex;flex-wrap:wrap;gap:6px}.options button,.submit-answers{min-height:31px;padding:0 11px;border:1px solid #ffffff1e;border-radius:8px;background:#292c2e;color:#c6ccc4;font-size:10px;cursor:pointer}.options button:hover{border-color:#b7f34a66;color:var(--lime)}.options button.selected{border-color:#b7f34a88;background:#b7f34a18;color:var(--lime);box-shadow:inset 0 0 0 1px #b7f34a22}.questions small{display:block;margin-top:8px;color:#777e76;font-size:10px}.submit-answers{display:inline-flex;align-items:center;gap:6px;margin-top:10px;border:1px solid #8dcc31;background:#b7f34a;color:#18200f;font-weight:600;cursor:pointer;box-shadow:0 2px 8px #b7f34a22}.confirmation h4{display:flex;gap:6px;align-items:center;margin:0 0 7px;color:var(--lime);font-size:11px}.confirmation p{margin:0;padding:9px;border:1px solid #b7f34a30;border-radius:8px;background:#b7f34a08;line-height:1.6;white-space:pre-wrap}.view-confirmation{display:inline-flex;align-items:center;gap:5px;margin-top:7px;padding:5px 8px;border:1px solid #ffffff1b;border-radius:6px;background:#25292a;color:#c3c9c1;font-size:10px;cursor:pointer}.view-confirmation:hover{border-color:#b7f34a55;color:var(--lime)}.confirmation-viewer{min-width:min(580px,calc(100vw - 64px));max-width:100%}.confirmation-tabs{display:flex;gap:4px;padding:12px 16px 0}.confirmation-tabs button{padding:7px 10px;border:1px solid transparent;border-radius:6px;background:transparent;color:#9aa199;font-size:12px;cursor:pointer}.confirmation-tabs button.active{border-color:#ffffff20;background:#2a2d2e;color:#dfe6de}.confirmation-full-text{max-height:min(62dvh,560px);margin:12px 16px 16px;padding:14px;border:1px solid #ffffff16;border-radius:8px;background:#111315;color:#e0e5dd;font:12px/1.75 ui-monospace,Consolas,monospace;white-space:pre-wrap;overflow:auto;overscroll-behavior:contain}.input-wrap{display:flex;align-items:flex-end;gap:8px;margin:0 12px 12px;padding:8px 8px 8px 12px;border:1px solid #ffffff1f;border-radius:10px;background:#111315}.input-wrap textarea{flex:1;min-width:0;min-height:30px;max-height:90px;padding:5px 0;resize:none;outline:0;border:0;background:transparent;color:#e4e7e1;font-size:12px;line-height:20px}.input-wrap button{display:grid;place-items:center;width:31px;height:31px;border:0;border-radius:50%;background:var(--lime);color:#171914;cursor:pointer}.input-wrap button:disabled,footer button:disabled{opacity:.5;cursor:default}footer{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border-top:1px solid var(--line);background:#191b1c}footer span{display:flex;gap:5px;align-items:center;color:#969c94;font-size:10px}footer button{display:flex;gap:6px;align-items:center;height:32px;padding:0 11px;border:1px solid #8dcc31;border-radius:8px;background:#b7f34a;color:#18200f;font-size:10px;font-weight:600;cursor:pointer}footer button:hover{background:#c5fa69}.collaboration-ui button:disabled{opacity:.5;cursor:default}@keyframes blink{0%,60%,100%{opacity:.25}30%{opacity:1}}
.confirmation-full-text{scrollbar-width:none}.confirmation-full-text::-webkit-scrollbar{display:none}
</style>
